import { bind, BindingModel, bindPassive } from '@game-studio/bindings';
import { SpinProfileSequence } from '../values/SpinProfileSequence';
import { GRService } from '../..';
export class GRModel extends BindingModel {

    public readonly ON_SCREEN_REELS: string = '_onScreenReels';
    public readonly SPIN_SPEED_VALUES: string = '_spinSpeedValues';
    public readonly SPIN_STATE: string = '_spinState';

    @bind() public spinComplete: boolean = false;
    @bind() public startPosition: number[] = [];
    @bind() public targetPosition: number[] = [];
    @bind() public displayReels: number[][] = [];
    @bindPassive() public selectedSpinProfileSequence: SpinProfileSequence;

    protected _spinState: number[] = [];
    protected _onScreenReels: number[][] = [];
    protected _spinSpeedValues: number[] = [];

    protected _service: GRService;

    constructor(service: GRService) {
        super();
        this._service = service;
    }

    public set onScreenReels(reels: number[][]) {
        this._onScreenReels = reels;
        this._service.eventFire.serviceEvent.ON_SCREENREELS_CHANGED(reels);
        this.invalidate(this.ON_SCREEN_REELS);
    }

    public get onScreenReels(): number[][] {
        return (this._onScreenReels);
    }

    public set spinSpeedValues(speedValues: number[]) {
        this._spinSpeedValues = speedValues;
        this._service.eventFire.serviceEvent.ON_SPIN_SPEED_CHANGED(speedValues);
        this.invalidate(this.SPIN_SPEED_VALUES);
    }

    public get spinSpeedValues() {
        return (this._spinSpeedValues);
    }

    public set spinState(states: number[]) {
        this._spinState = states;
        this._service.eventFire.serviceEvent.ON_SPIN_STATE_CHANGED(states);
        this.invalidate(this.SPIN_STATE);
    }

    public get spinState(): number[] {
        return (this._spinState);
    }
}